# Terraform Module: S3 + RDS + IAM

Here is a complete, production-ready Terraform module structure that provisions S3 bucket, RDS PostgreSQL, and IAM role with dev/prod environment support via tfvars files.

## Directory Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
└── README.md
```

## Root Module

### `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Uncomment to use remote backend
  # backend "s3" {
  #   bucket         = "terraform-state-bucket"
  #   key            = "infrastructure/terraform.tfstate"
  #   region         = "us-east-1"
  #   encrypt        = true
  #   dynamodb_table = "terraform-locks"
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project_name
      ManagedBy   = "Terraform"
      CreatedAt   = timestamp()
    }
  }
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name              = var.bucket_name
  versioning_enabled       = var.s3_versioning_enabled
  encryption_type          = var.s3_encryption_type
  kms_key_id               = var.s3_kms_key_id
  enable_replication       = var.environment == "prod" ? true : false
  replication_destination  = var.replication_destination
  replication_destination_region = var.replication_destination_region

  tags = {
    Name = var.bucket_name
  }
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  identifier              = var.rds_identifier
  instance_class          = var.rds_instance_class
  allocated_storage       = var.rds_allocated_storage
  engine_version          = var.rds_engine_version
  database_name           = var.rds_database_name
  username                = var.rds_username
  password                = random_password.rds_password.result
  deletion_protection     = var.rds_deletion_protection
  backup_retention_days   = var.rds_backup_retention_days
  multi_az                = var.environment == "prod" ? true : false
  storage_encrypted       = true
  skip_final_snapshot     = var.environment == "dev" ? true : false
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.default.name
  publicly_accessible     = false

  tags = {
    Name = var.rds_identifier
  }
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  role_name              = var.iam_role_name
  service_account_name   = var.iam_service_account_name
  s3_bucket_arn          = module.s3.bucket_arn
  s3_bucket_name         = module.s3.bucket_name
  rds_resource_id        = module.rds.resource_id
  enable_oidc_trust      = var.environment == "prod" ? true : false
  oidc_provider_arn      = var.oidc_provider_arn
  oidc_subject_condition = var.oidc_subject_condition

  tags = {
    Name = var.iam_role_name
  }
}

# Generate secure RDS password
resource "random_password" "rds_password" {
  length  = 32
  special = true
}

# Store RDS password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "rds_password" {
  name                    = "${var.rds_identifier}-password"
  recovery_window_in_days = 7

  tags = {
    Name = "${var.rds_identifier}-password"
  }
}

resource "aws_secretsmanager_secret_version" "rds_password" {
  secret_id = aws_secretsmanager_secret.rds_password.id
  secret_string = jsonencode({
    username = var.rds_username
    password = random_password.rds_password.result
    engine   = "postgres"
    host     = module.rds.endpoint
    port     = module.rds.port
    dbname   = var.rds_database_name
  })
}

# VPC and Networking (required for RDS)
resource "aws_db_subnet_group" "default" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = var.db_subnet_ids

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${var.project_name}-rds-sg"
  description = "Security group for RDS database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.rds_allowed_cidr_blocks

    description = "PostgreSQL access"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]

    description = "Allow all outbound traffic"
  }

  tags = {
    Name = "${var.project_name}-rds-sg"
  }
}
```

### `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev, prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
}

# VPC and Networking
variable "vpc_id" {
  description = "VPC ID for RDS and security groups"
  type        = string
}

variable "db_subnet_ids" {
  description = "Subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "rds_allowed_cidr_blocks" {
  description = "CIDR blocks allowed to connect to RDS"
  type        = list(string)
  default     = []
}

# S3 Configuration
variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "s3_versioning_enabled" {
  description = "Enable S3 versioning"
  type        = bool
  default     = true
}

variable "s3_encryption_type" {
  description = "S3 encryption type: 'AES256' or 'aws:kms'"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms"], var.s3_encryption_type)
    error_message = "Encryption type must be 'AES256' or 'aws:kms'."
  }
}

variable "s3_kms_key_id" {
  description = "KMS key ID for S3 encryption (required if encryption_type is 'aws:kms')"
  type        = string
  default     = null
}

variable "replication_destination" {
  description = "S3 bucket name for replication destination (prod only)"
  type        = string
  default     = null
}

variable "replication_destination_region" {
  description = "AWS region for replication destination (prod only)"
  type        = string
  default     = "us-west-2"
}

# RDS Configuration
variable "rds_identifier" {
  description = "RDS instance identifier"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class (e.g., db.t3.micro, db.t3.medium)"
  type        = string
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.3"
}

variable "rds_database_name" {
  description = "Initial database name"
  type        = string
  default     = "applicationdb"
}

variable "rds_username" {
  description = "Database master username"
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "rds_deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "rds_backup_retention_days" {
  description = "Number of days to retain backups"
  type        = number
  default     = 7
  validation {
    condition     = var.rds_backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

# IAM Configuration
variable "iam_role_name" {
  description = "IAM role name"
  type        = string
}

variable "iam_service_account_name" {
  description = "IAM service account name"
  type        = string
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN for prod environments"
  type        = string
  default     = null
}

variable "oidc_subject_condition" {
  description = "OIDC subject condition (e.g., sts.amazonaws.com:sub)"
  type        = string
  default     = null
}
```

### `outputs.tf`

```hcl
output "s3_bucket_name" {
  description = "S3 bucket name"
  value       = module.s3.bucket_name
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.s3.bucket_arn
}

output "s3_bucket_region" {
  description = "S3 bucket region"
  value       = module.s3.bucket_region
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = module.rds.endpoint
  sensitive   = true
}

output "rds_port" {
  description = "RDS instance port"
  value       = module.rds.port
}

output "rds_resource_id" {
  description = "RDS instance resource ID"
  value       = module.rds.resource_id
}

output "iam_role_arn" {
  description = "IAM role ARN"
  value       = module.iam.role_arn
}

output "iam_role_name" {
  description = "IAM role name"
  value       = module.iam.role_name
}

output "secret_arn" {
  description = "AWS Secrets Manager secret ARN containing RDS credentials"
  value       = aws_secretsmanager_secret.rds_password.arn
  sensitive   = true
}

output "connection_string" {
  description = "RDS connection string (reference via Secrets Manager)"
  value       = "postgres://${var.rds_username}:***@${module.rds.endpoint}:${module.rds.port}/${var.rds_database_name}"
  sensitive   = true
}
```

## Modules

### S3 Module: `modules/s3/main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  tags = var.tags
}

# Enable versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_type
      kms_master_key_id = var.encryption_type == "aws:kms" ? var.kms_key_id : null
    }
    bucket_key_enabled = true
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication configuration (prod only)
resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.this]

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket       = "arn:aws:s3:::${var.replication_destination}"
      storage_class = "STANDARD"
    }
  }
}

# IAM role for replication (prod only)
resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name = "${var.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name = "${var.bucket_name}-replication-policy"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "arn:aws:s3:::${var.replication_destination}/*"
      }
    ]
  })
}

resource "aws_s3_bucket" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = var.replication_destination

  tags = var.tags
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}
```

